{
  "items": [
    {
      "name": "Nat.pow_lt_of_lt_clog",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, y < Nat.clog b x → b ^ y < x"
    },
    {
      "name": "Nat.pow_lt_iff_lt_clog",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, b ^ y < x ↔ y < Nat.clog b x"
    },
    {
      "name": "FloorSemiring.eventually_mul_pow_lt_factorial_sub",
      "module_name": "Mathlib.Order.Filter.AtTopBot.Floor",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Ring K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] [FloorSemiring K] (a c : K) (d : ℕ),\n  ∀ᶠ (n : ℕ) in Filter.atTop, a * c ^ n < ↑(n - d).factorial"
    },
    {
      "name": "Int.self_le_zpow_clog",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semifield R] [inst_1 : LinearOrder R] [IsStrictOrderedRing R] [inst_3 : FloorSemiring R]\n  {b : ℕ}, 1 < b → ∀ (r : R), r ≤ ↑b ^ Int.clog b r"
    },
    {
      "name": "Nat.pow_pred_clog_lt_self",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x : ℕ}, 1 < x → b ^ (Nat.clog b x).pred < x"
    }
  ]
}
